import type {
  FoundryFolder,
  FoundryPackCollection,
  FoundryPackFolder,
} from "../../../types/foundry";

function childrenOf(folder: FoundryFolder, folders: FoundryFolder[]): FoundryFolder[] {
  return folders.filter((candidate) => candidate.folder?.id === folder.id);
}

export function descendantIds(folder: FoundryFolder, folders: FoundryFolder[]): Set<string> {
  const ids = new Set<string>([folder.id]);
  for (const child of childrenOf(folder, folders)) {
    for (const id of descendantIds(child, folders)) ids.add(id);
  }
  return ids;
}

export function declaredPackIds(spec: FoundryPackFolder, packageId: string): Set<string> {
  const ids = new Set(spec.packs.map((name) => `${packageId}.${name}`));
  for (const child of spec.folders) {
    for (const id of declaredPackIds(child, packageId)) ids.add(id);
  }
  return ids;
}

export function folderContainsOwnPack(
  folder: FoundryFolder,
  folders: FoundryFolder[],
  packs: FoundryPackCollection,
  expectedIds: Set<string>,
): boolean {
  const ids = descendantIds(folder, folders);
  let ownsExpectedPack = false;
  for (const [packId, pack] of packs.entries()) {
    if (!pack.folder || !ids.has(pack.folder.id)) continue;
    if (expectedIds.has(packId)) ownsExpectedPack = true;
  }
  return ownsExpectedPack;
}

export function folderContainsForeignPack(
  packageId: string,
  folder: FoundryFolder,
  folders: FoundryFolder[],
  packs: FoundryPackCollection,
): boolean {
  const ids = descendantIds(folder, folders);
  for (const [packId, pack] of packs.entries()) {
    if (pack.folder && ids.has(pack.folder.id) && !packId.startsWith(`${packageId}.`)) return true;
  }
  return false;
}

export function assertUniqueDeclaration(specs: FoundryPackFolder[]): void {
  const paths = new Set<string>();
  const packs = new Set<string>();
  function visit(spec: FoundryPackFolder, parent: string): void {
    const path = `${parent}/${spec.name}`;
    if (paths.has(path)) throw new Error(`Duplicate Compendium folder declaration: ${path}`);
    paths.add(path);
    for (const name of spec.packs) {
      if (packs.has(name)) throw new Error(`Duplicate Compendium pack declaration: ${name}`);
      packs.add(name);
    }
    for (const child of spec.folders) visit(child, path);
  }
  for (const spec of specs) visit(spec, "");
}
