import type { FoundryFolder, FoundryGame } from "../../../types/foundry";

/** Move every child and pack before deleting only the emptied duplicate container. */
export async function mergeCompendiumFolder(
  source: FoundryFolder,
  target: FoundryFolder,
  folders: FoundryFolder[],
  packs: FoundryGame["packs"],
): Promise<void> {
  for (const [, pack] of packs.entries()) {
    if (pack.folder?.id !== source.id) continue;
    await pack.setFolder(target);
    if (pack.folder?.id !== target.id)
      throw new Error(`Could not move a pack out of ${source.name}.`);
  }
  for (const child of folders.filter((f) => f.folder?.id === source.id)) {
    await child.update({ folder: target.id });
    if (child.folder?.id !== target.id) throw new Error(`Could not move folder ${child.name}.`);
  }
  const deleted = await source.delete({ deleteSubfolders: false, deleteContents: false });
  if (!deleted) throw new Error(`Could not delete empty duplicate folder ${source.name}.`);
  folders.splice(folders.indexOf(source), 1);
}

/** Only declared folders and packs belong inside the module's managed hierarchy. */
export async function ejectUnrelatedCompendiums(
  folders: FoundryFolder[],
  packs: FoundryGame["packs"],
  managed: ReadonlySet<string>,
  declared: ReadonlySet<string>,
): Promise<void> {
  for (const [id, pack] of packs.entries()) {
    if (pack.folder && managed.has(pack.folder.id) && !declared.has(id)) {
      await pack.setFolder(null);
      if (pack.folder) throw new Error(`Could not move unrelated pack ${id} to the sidebar root.`);
    }
  }
  for (const folder of folders) {
    if (folder.folder && managed.has(folder.folder.id) && !managed.has(folder.id)) {
      await folder.update({ folder: null });
      if (folder.folder)
        throw new Error(`Could not move unrelated folder ${folder.name} to the sidebar root.`);
    }
  }
}
