import { registerPackageApi } from "../foundry/api/register-package-api";
import { registerModuleSettings } from "../foundry/settings";
import { registerCompendiumSidebarSetting } from "../foundry/compendiums/settings";
import { tidyCompendiumSidebarIfEnabled } from "../foundry/compendiums/tidy";
import { registerHandbookTestContextOptions } from "../wfrp/mutants-handbook/context-options";
import {
  registerMutationAutomationHooks,
  restoreEnabledMutationLights,
} from "../wfrp/mutants-handbook/automation/hooks";
import { migrateOwnedMutationAutomation } from "../wfrp/mutants-handbook/automation/migration";
import { reportMutationError } from "../wfrp/mutants-handbook/messages";
import { installMutantsHandbookReplacement } from "../wfrp/mutants-handbook/replacement";
import { registerMutationCompanionHooks } from "../wfrp/mutants-handbook/actions/companions";
import { registerCorruptionChatHooks } from "../wfrp/mutants-handbook/corruption-chat";
import { registerRatterSpeciesHooks } from "../foundry/integrations/ratter-species";

export function registerModuleHooks(): void {
  Hooks.once("init", () => {
    registerModuleSettings();
    registerPackageApi();
    registerHandbookTestContextOptions();
    registerCorruptionChatHooks();
    registerMutationAutomationHooks();
    registerMutationCompanionHooks();
    registerRatterSpeciesHooks();
  });

  Hooks.once("setup", () => {
    registerCompendiumSidebarSetting();
  });

  Hooks.once("ready", async () => {
    installMutantsHandbookReplacement();
    try {
      await tidyCompendiumSidebarIfEnabled();
    } catch (error) {
      console.error("Ratter Compendium sidebar tidy-up failed.", error);
      ui.notifications.error(
        "Ratter Compendium cleanup failed and may be incomplete. See the console for details.",
      );
    }
    try {
      await migrateOwnedMutationAutomation();
      await restoreEnabledMutationLights(Reflect.get(globalThis, "canvas"));
    } catch (error) {
      reportMutationError(error);
    }
  });
}
