import type { ChaosPatron } from "../../../types/mutants-handbook";

const BESTIAL_NOTES: Readonly<Record<ChaosPatron, string>> = {
  khorne: "Use only Ape/Monkey, Bear, Boar/Pig, Bovine, Canine, or Goat/Sheep.",
  nurgle:
    "Use only Ape/Monkey, Bear, Boar/Pig, Bovine, Deer/Elk, Goat/Sheep, Horse/Camel, Insect, Pachyderm, or Spider.",
  slaanesh: "Use only Amphibian, Arthropod, Fish, Feline, Lizard/Snake, or Mollusca.",
  tzeentch: "Use only Bat, Bird, Fish, Insect, Mollusca, or Spider.",
};

const UNNATURAL_NOTES: Readonly<Record<ChaosPatron, string>> = {
  khorne: "Use only Daemonic, Mechanoid, or Metal.",
  nurgle: "Use only Daemonic, Fenbeast, or Undead.",
  slaanesh: "Use only Daemonic or Metal.",
  tzeentch: "Use only Daemonic or Mechanoid.",
};

const ADDICTION_NOTES: Readonly<Record<ChaosPatron, string>> = {
  khorne: "Use only Destruction, Drugs, or Pain.",
  nurgle: "Use only Devotion, Gluttony, or Service.",
  slaanesh: "Use only Art, Lust, or Pain.",
  tzeentch: "Use only Gambling, Greed, or Theft.",
};

const PROTECTIVE_SKIN_NOTES: Partial<Record<ChaosPatron, string>> = {
  khorne: "Use only Leathery Hide, Fur, or Metal.",
  slaanesh: "Use only Rubbery Skin, Scales, or Carapace.",
};

const BESTIAL_RESULTS = new Set([
  "bestial arms",
  "bestial body",
  "bestial head",
  "bestial legs",
  "bestial limbs",
]);
const UNNATURAL_RESULTS = new Set([
  "unnatural arms",
  "unnatural body",
  "unnatural head",
  "unnatural legs",
  "unnatural limbs",
]);

export function getPatronResultNote(patron: ChaosPatron, mutationName: string): string | undefined {
  const name = mutationName.trim().toLowerCase();

  if (BESTIAL_RESULTS.has(name)) {
    return BESTIAL_NOTES[patron];
  }

  if (UNNATURAL_RESULTS.has(name)) {
    return UNNATURAL_NOTES[patron];
  }

  if (name === "addiction") {
    return ADDICTION_NOTES[patron];
  }

  if (name === "mark of chaos") {
    return `The mark is the Mark of ${patron.charAt(0).toUpperCase()}${patron.slice(1)}.`;
  }

  if (name === "protective skin") {
    return PROTECTIVE_SKIN_NOTES[patron];
  }

  if (patron === "khorne" && name === "prejudice") {
    return "This automation treats Prejudice as mental for Corruption reduction and mutation limits.";
  }

  if (patron === "nurgle" && name === "corrupted blood") {
    return "The source attaches a mismatched footnote listing Leathery Hide, Bark, and Carapace; the GM must decide how to handle it.";
  }

  return undefined;
}
