import { FLAG_SCOPE } from "../../constants.ts";

export const CUSTOMIZERS_ID = "wfrp4e-customizer-apps";
export const SPECIES_TYPE = `${CUSTOMIZERS_ID}.species`;
export const SPECIES_PACK = "fvtt-wfrp-ratter.ratter-species";
export const SPECIES_NOTICE =
  "Ratter Species requires Drowsy's WFRP4e Customizers to be enabled and its Species Item type registered. Enable Customizers and reload the world before opening or importing these Items.";

interface SpeciesReference {
  uuid?: string;
}

export interface SpeciesDocument {
  id: string;
  uuid: string;
  name: string;
  type?: string;
  pack?: string;
  parent?: unknown;
  flags?: { [FLAG_SCOPE]?: { speciesTemplate?: { version: number; key: string } } };
  _stats?: { compendiumSource?: string };
  system?: {
    subspeciesOf?: SpeciesReference;
    tables?: { career?: SpeciesReference };
  };
  update(data: Record<string, unknown>): Promise<unknown>;
}

type PackMethod = (...args: unknown[]) => Promise<unknown>;
export interface SpeciesPack {
  getDocument: PackMethod;
  getDocuments: PackMethod;
  importAll: PackMethod;
  importDialog: PackMethod;
}

interface WorldCollection {
  contents: SpeciesDocument[];
  importFromCompendium(
    pack: { collection: string },
    id: string,
    ...args: unknown[]
  ): Promise<SpeciesDocument | null>;
}

export interface SpeciesEnvironment {
  modules: Map<string, { active?: boolean }>;
  models: Record<string, unknown>;
  packs: Map<string, { collection: string }>;
  items: WorldCollection;
  tables: WorldCollection;
}

export function speciesAvailable(
  environment: Pick<SpeciesEnvironment, "modules" | "models">,
): boolean {
  return (
    environment.modules.get(CUSTOMIZERS_ID)?.active === true &&
    typeof environment.models[SPECIES_TYPE] === "function"
  );
}

const guarded = new WeakSet<SpeciesPack>();
const guardedImports = new WeakSet<WorldCollection>();

/** Foundry's import convenience method assumes getDocument always returns a document. */
export function guardSpeciesImports(
  collection: WorldCollection,
  available: () => boolean,
  notify: (message: string) => void,
): void {
  if (guardedImports.has(collection)) return;
  guardedImports.add(collection);
  const original = collection.importFromCompendium;
  collection.importFromCompendium = async function (pack, id, ...args) {
    if (pack.collection === SPECIES_PACK && !available()) {
      notify(SPECIES_NOTICE);
      return null;
    }
    return original.call(this, pack, id, ...args);
  };
}

/** Leave the native index readable, but do not instantiate unsupported Items. */
export function guardSpeciesPack(
  pack: SpeciesPack,
  available: () => boolean,
  notify: (message: string) => void,
): void {
  if (guarded.has(pack)) return;
  guarded.add(pack);
  for (const method of ["getDocument", "getDocuments", "importAll", "importDialog"] as const) {
    const original = pack[method];
    pack[method] = async function (...args: unknown[]) {
      if (available()) return original.apply(this, args);
      notify(SPECIES_NOTICE);
      return method === "getDocuments" || method === "importAll" ? [] : null;
    };
  }
}

export function isRatterSpecies(document: SpeciesDocument): boolean {
  return (
    document.type === SPECIES_TYPE && document.flags?.[FLAG_SCOPE]?.speciesTemplate?.version === 1
  );
}

async function worldReference(
  uuid: string | undefined,
  pack: string,
  kind: string,
  collection: WorldCollection,
  packs: SpeciesEnvironment["packs"],
): Promise<Record<string, string> | undefined> {
  const prefix = `Compendium.${pack}.${kind}.`;
  if (!uuid?.startsWith(prefix)) return;
  const id = uuid.slice(prefix.length);
  if (!/^[A-Za-z0-9]{16}$/.test(id)) throw new Error(`Invalid Ratter species dependency: ${uuid}`);
  const existing = collection.contents.find(
    (document) => document._stats?.compendiumSource === uuid,
  );
  const compendium = packs.get(pack);
  if (!compendium) throw new Error(`Missing Ratter dependency pack: ${pack}`);
  const document = existing ?? (await collection.importFromCompendium(compendium, id));
  if (!document) throw new Error(`Could not import Ratter species dependency: ${uuid}`);
  return { uuid: document.uuid, id: document.id, name: document.name };
}

/** Customizers 1.11 reads world Items/tables and does not resolve compendium parents. */
export async function repairSpeciesReferences(
  document: SpeciesDocument,
  environment: SpeciesEnvironment,
): Promise<boolean> {
  if (
    document.parent ||
    document.pack ||
    !isRatterSpecies(document) ||
    !speciesAvailable(environment)
  )
    return false;
  const updates: Record<string, unknown> = {};
  const parent = await worldReference(
    document.system?.subspeciesOf?.uuid,
    SPECIES_PACK,
    "Item",
    environment.items,
    environment.packs,
  );
  const career = await worldReference(
    document.system?.tables?.career?.uuid,
    "fvtt-wfrp-ratter.ratter-10-tables",
    "RollTable",
    environment.tables,
    environment.packs,
  );
  if (parent) updates["system.subspeciesOf"] = parent;
  if (career) updates["system.tables.career"] = career;
  if (!Object.keys(updates).length) return false;
  await document.update(updates);
  return true;
}

function environment(): SpeciesEnvironment {
  const currentGame = Reflect.get(globalThis, "game") as SpeciesEnvironment;
  const config = Reflect.get(globalThis, "CONFIG") as {
    Item: { dataModels: Record<string, unknown> };
  };
  return {
    modules: currentGame.modules,
    models: config.Item.dataModels,
    packs: currentGame.packs,
    items: currentGame.items,
    tables: currentGame.tables,
  };
}

export function registerRatterSpeciesHooks(): void {
  const installGuard = () => {
    const pack = game?.packs.get(SPECIES_PACK) as SpeciesPack | undefined;
    if (pack)
      guardSpeciesPack(
        pack,
        () => speciesAvailable(environment()),
        (message) => ui.notifications.warn(message),
      );
    guardSpeciesImports(
      environment().items,
      () => speciesAvailable(environment()),
      (message) => ui.notifications.warn(message),
    );
  };
  Hooks.on("setup", installGuard);
  Hooks.once("ready", () => {
    installGuard();
    if (game?.user.isGM && !speciesAvailable(environment())) ui.notifications.warn(SPECIES_NOTICE);
  });

  // Core's entry-click handler also assumes a non-null document. Block entry actions
  // before that handler runs while leaving the pack's native index visible.
  const directories = new WeakSet<HTMLElement>();
  Hooks.on("renderCompendium", (application, element) => {
    const app = application as { collection?: { collection: string } };
    if (
      app.collection?.collection !== SPECIES_PACK ||
      !(element instanceof HTMLElement) ||
      directories.has(element)
    )
      return;
    directories.add(element);
    for (const type of ["click", "contextmenu", "dragstart"])
      element.addEventListener(
        type,
        (event) => {
          if (
            speciesAvailable(environment()) ||
            !(event.target instanceof Element) ||
            !event.target.closest("[data-entry-id]")
          )
            return;
          event.preventDefault();
          event.stopImmediatePropagation();
          ui.notifications.warn(SPECIES_NOTICE);
        },
        { capture: true },
      );
  });

  // Foundry imports a batch before dispatching createItem. Serialize dependency imports
  // so all bloodlines reuse the same parent and tables, including individual imports.
  const pending = new Set<SpeciesDocument>();
  let repairing = false;
  const drain = async () => {
    if (repairing) return;
    repairing = true;
    let changed = false;
    try {
      while (pending.size) {
        const document = pending.values().next().value;
        if (!document) break;
        pending.delete(document);
        changed = (await repairSpeciesReferences(document, environment())) || changed;
      }
      if (changed)
        ui.notifications.warn(
          "Ratter species imported and world references linked. Reload the world to register Vampire and its bloodlines in Customizers character creation. Choose a starting bloodline gift and five different Weaknesses manually.",
        );
    } catch (error) {
      pending.clear();
      ui.notifications.error(
        `Ratter species references could not be linked: ${error instanceof Error ? error.message : String(error)}. Correct the world parent/career references before reloading.`,
      );
    } finally {
      repairing = false;
    }
  };
  Hooks.on("createItem", (value, _options, userId) => {
    const document = value as SpeciesDocument;
    if (
      userId !== game?.user.id ||
      !game?.user.isGM ||
      document.parent ||
      document.pack ||
      !isRatterSpecies(document)
    )
      return;
    pending.add(document);
    // Wait until the current Foundry document batch has finished its hooks.
    void Promise.resolve().then(drain);
  });
}
