import { createPackageApi } from "./create-package-api";
import { PACKAGE_ID } from "../../constants";

export function registerPackageApi(): void {
  if (!game) {
    throw new Error("Foundry game global is unavailable during module API registration.");
  }

  const moduleEntry = game.modules.get(PACKAGE_ID);

  if (!moduleEntry) {
    throw new Error(`Foundry module registry entry was not found for ${PACKAGE_ID}.`);
  }

  moduleEntry.api = createPackageApi();
}
