import type { PackageApi } from "../../../types/api/PackageApi";
import { PACKAGE_ID, PACKAGE_TITLE } from "../../constants";
import { checkMutantsHandbookCorruptionByUuid } from "../../wfrp/mutants-handbook/check";
import {
  reconcileMutationAutomation,
  removeMutationGrantOwner,
} from "../../wfrp/mutants-handbook/automation/grant-reconciliation";
import {
  applyMutationActionOutcome,
  prepareMutationActionDialog,
  recordMutationActionUse,
  resolveMutationActionTest,
  useMutationAction,
} from "../../wfrp/mutants-handbook/actions";

export function createPackageApi(): PackageApi {
  return {
    applyMutationActionOutcome,
    checkMutantsHandbookCorruption: checkMutantsHandbookCorruptionByUuid,
    id: PACKAGE_ID,
    logStatus() {
      console.log(`${PACKAGE_TITLE} is loaded.`);
    },
    prepareMutationActionDialog,
    recordMutationActionUse,
    reconcileMutationAutomation,
    removeMutationGrantOwner,
    resolveMutationActionTest,
    title: PACKAGE_TITLE,
    useMutationAction,
  };
}
