import { PACKAGE_ID } from "../../constants";

export const KEEP_COMPENDIUMS_TIDY_SETTING = "keepCompendiumsTidy";

export function registerCompendiumSidebarSetting(): void {
  if (!game?.user)
    throw new Error("Foundry user is unavailable during Compendium tidy setting registration.");
  game.settings.register(PACKAGE_ID, KEEP_COMPENDIUMS_TIDY_SETTING, {
    config: game.user.isGM === true,
    default: false,
    hint: "FVTT_WFRP_RATTER.Settings.KeepCompendiumsTidy.Hint",
    name: "FVTT_WFRP_RATTER.Settings.KeepCompendiumsTidy.Name",
    scope: "world",
    type: Boolean,
  });
}
