export function mutationNumber(value: unknown, fallback = 0): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function mutationScriptData(
  label: string,
  trigger: string,
  script: string,
): Record<string, unknown> {
  return {
    async: true,
    label,
    options: {
      activateScript: "return true;",
      hideScript: "",
      submissionScript: "",
      targeter: false,
    },
    script,
    trigger,
  };
}

export function mutationEffectDuration(
  rounds?: number,
  seconds?: number,
): Record<string, number | null> {
  return {
    combat: null,
    rounds: rounds ?? null,
    seconds: seconds ?? null,
    startRound: null,
    startTime: null,
    startTurn: null,
    turns: null,
  };
}
