import { queueFolderTidy } from "./queue";
import { mergeCompendiumFolder, ejectUnrelatedCompendiums } from "./merge";
import { PACKAGE_ID } from "../../constants";
import { KEEP_COMPENDIUMS_TIDY_SETTING } from "./settings";
import type { FoundryFolder, FoundryGame, FoundryPackFolder } from "../../../types/foundry";

import {
  descendantIds,
  declaredPackIds,
  folderContainsOwnPack,
  assertUniqueDeclaration,
} from "../../functions/compendiums/folders";

/** Order this module's root children without changing any undeclared folder. */
async function restoreRootChildOrder(
  children: FoundryFolder[],
  allFolders: FoundryFolder[],
  root: FoundryFolder,
): Promise<void> {
  if (children.length < 2) return;
  if (
    children.every(
      (folder, index) =>
        typeof folder.sort === "number" &&
        Number.isFinite(folder.sort) &&
        (index === 0 || folder.sort > (children[index - 1]?.sort ?? Number.NEGATIVE_INFINITY)),
    )
  )
    return;

  const highestSort = Math.max(
    0,
    ...allFolders
      .filter((folder) => folder.folder?.id === root.id)
      .map((folder) =>
        typeof folder.sort === "number" && Number.isFinite(folder.sort) ? folder.sort : 0,
      ),
  );
  for (const [index, folder] of children.entries()) {
    const sort = highestSort + (index + 1) * 100_000;
    if (!Number.isSafeInteger(sort))
      throw new Error(`Cannot safely sort Compendium folders under ${root.name}.`);
    await folder.update({ sort });
  }
}

/** Repair only this module's declared Compendium sidebar hierarchy and pack locations. */
export async function tidyCompendiumSidebar(
  currentGame: FoundryGame,
  createFolder: (data: Record<string, unknown>) => Promise<FoundryFolder | null>,
): Promise<void> {
  await queueFolderTidy(currentGame, () => runCompendiumTidy(currentGame, createFolder));
}

async function runCompendiumTidy(
  currentGame: FoundryGame,
  createFolder: (data: Record<string, unknown>) => Promise<FoundryFolder | null>,
): Promise<void> {
  if (currentGame.user.isGM !== true || currentGame.user.isActiveGM !== true) return;
  const module = currentGame.modules.get(PACKAGE_ID);
  if (!module) throw new Error(`Foundry module registry entry was not found for ${PACKAGE_ID}.`);
  const specs = Array.from(module.packFolders ?? []);
  assertUniqueDeclaration(specs);
  if (specs.length === 0) return;
  for (const spec of specs) {
    for (const packId of declaredPackIds(spec, PACKAGE_ID)) {
      if (!currentGame.packs.has(packId))
        throw new Error(`Declared Compendium ${packId} was not found.`);
    }
  }
  const folders = Array.from(currentGame.folders ?? []).filter(
    (folder) => folder.type === "Compendium",
  );

  const claimed = new Set<string>();

  async function reconcile(
    spec: FoundryPackFolder,
    parent: FoundryFolder | null,
  ): Promise<FoundryFolder> {
    const expectedIds = declaredPackIds(spec, PACKAGE_ID);
    // Prefer a sibling already holding the declared packs; IDs break ties consistently.
    // Declared names identify managed folders, even when unrelated packs were put inside.
    const eligible = folders
      .filter(
        (candidate) =>
          candidate.name === spec.name &&
          !claimed.has(candidate.id) &&
          (!parent || !descendantIds(candidate, folders).has(parent.id)),
      )
      .sort(
        (a, b) =>
          Number(folderContainsOwnPack(b, folders, currentGame.packs, expectedIds)) -
            Number(folderContainsOwnPack(a, folders, currentGame.packs, expectedIds)) ||
          a.id.localeCompare(b.id),
      );
    let folder: FoundryFolder | null | undefined = eligible.find(
      (candidate) => (candidate.folder?.id ?? null) === (parent?.id ?? null),
    );
    if (!folder) {
      folder = eligible.find(
        (candidate) =>
          folderContainsOwnPack(candidate, folders, currentGame.packs, expectedIds) &&
          (!parent || !descendantIds(candidate, folders).has(parent.id)),
      );
      if (folder) {
        if (parent && descendantIds(folder, folders).has(parent.id))
          throw new Error(`Moving ${spec.name} under ${parent.name} would make a folder cycle.`);
        const parentId = parent?.id ?? null;
        const updated = await folder.update({ folder: parentId });
        if (updated === undefined && (folder.folder?.id ?? null) !== parentId)
          throw new Error(
            `Could not move Compendium folder ${spec.name}; the update was not applied.`,
          );
      } else {
        folder = await createFolder({
          name: spec.name,
          type: "Compendium",
          folder: parent?.id ?? null,
          sorting: spec.sorting,
          ...(spec.color ? { color: spec.color } : {}),
        });
        if (!folder) throw new Error(`Could not create Compendium folder ${spec.name}.`);
        folders.push(folder);
      }
    }
    claimed.add(folder.id);
    for (const duplicate of eligible) {
      if (duplicate.id === folder.id) continue;
      if (
        (duplicate.folder?.id ?? null) !== (parent?.id ?? null) &&
        !folderContainsOwnPack(duplicate, folders, currentGame.packs, expectedIds)
      )
        continue;
      if (descendantIds(duplicate, folders).has(folder.id))
        throw new Error(`Cannot merge ancestor folder ${duplicate.name} into its descendant.`);
      await mergeCompendiumFolder(duplicate, folder, folders, currentGame.packs);
    }
    const changes: Record<string, unknown> = {};
    if (folder.sorting !== spec.sorting) changes["sorting"] = spec.sorting;
    if (
      spec.color !== undefined &&
      spec.color !== null &&
      String(folder.color) !== String(spec.color)
    )
      changes["color"] = String(spec.color);
    if (Object.keys(changes).length > 0) {
      const updated = await folder.update(changes);
      // An unchanged update is harmless if the folder already has the requested metadata.
      if (
        updated === undefined &&
        (folder.sorting !== spec.sorting ||
          (spec.color !== undefined &&
            spec.color !== null &&
            String(folder.color) !== String(spec.color)))
      )
        throw new Error(
          `Could not configure Compendium folder ${spec.name}; the update was not applied.`,
        );
    }

    for (const name of spec.packs) {
      const packId = `${PACKAGE_ID}.${name}`;
      const pack = currentGame.packs.get(packId);
      if (!pack) throw new Error(`Declared Compendium ${packId} was not found.`);
      if (pack.folder?.id !== folder.id) await pack.setFolder(folder);
    }
    const children: FoundryFolder[] = [];
    for (const child of spec.folders) children.push(await reconcile(child, folder));
    if (!parent && spec.sorting === "m") await restoreRootChildOrder(children, folders, folder);
    return folder;
  }

  for (const spec of specs) await reconcile(spec, null);
  const declared = new Set(specs.flatMap((spec) => [...declaredPackIds(spec, PACKAGE_ID)]));
  await ejectUnrelatedCompendiums(folders, currentGame.packs, claimed, declared);
}

export async function tidyCompendiumSidebarIfEnabled(): Promise<void> {
  if (!game?.user.isGM || !game.user.isActiveGM) return;
  if (game.settings.get(PACKAGE_ID, KEEP_COMPENDIUMS_TIDY_SETTING) !== true) return;
  await tidyCompendiumSidebar(game, (data) => CONFIG.Folder.documentClass.create(data));
}
